import type { PlaybookCopy } from './findingPlaybooks';
import lighthouseCatalogue from './lighthouseAuditCatalogue.json' with { type: 'json' };

// Each row names the problem, its location, the change and the observable result.
// Shared rows are restricted to rules with the same remediation, not just the same tool.
type Guidance = [title: string, problem: string, location: string, correction: string, verification: string];
type Group = { keys: string[]; reference: string; verifiedAt: string; fr: PlaybookCopy; en: PlaybookCopy };
export const detailedRuleGuidance: Group[] = [];
function rule(ids: string[], fr: Guidance, en: Guidance, source = 'lighthouse', reference?: string) {
  const copy = ([title, impact, location, correction, verification]: Guidance, french: boolean): PlaybookCopy => ({
    title, impact, summary: correction, steps: [location, correction],
    detection: `${source === 'lighthouse' ? 'Lighthouse' : source === 'zap' ? 'OWASP ZAP' : 'SSL Labs'} ${french ? 'signale ce contrôle comme à examiner.' : 'flags this check for review.'} ${impact}`,
    expected: `${verification} ${french ? 'Relancer le même contrôle sur la même URL après modification.' : 'Rerun the same check on the same URL after the change.'}`,
    example: '',
    limits: source === 'zap' ? (french ? 'Une alerte passive porte sur la réponse collectée ; elle ne démontre pas une exploitation. Confirmer la configuration et les parcours concernés avant modification.' : 'A passive alert concerns the collected response; it does not demonstrate exploitation. Confirm the configuration and affected journeys before making changes.') : source === 'lighthouse'
      ? (french ? 'Le signal concerne la page et les conditions mesurées. Un sélecteur ou un fichier absent du rapport doit être retrouvé dans le diagnostic source ; aucune ressource précise ne peut être déduite du score seul. Un contrôle automatisé ne remplace pas le test du parcours.' : 'The signal concerns the measured page and conditions. Locate any selector or file missing from the report in the source diagnosis; the score alone identifies no resource. An automated check does not replace testing the journey.')
      : (french ? 'Vérifier chaque terminaison TLS du domaine. Un résultat conservé ou mis en cache ne prouve pas que tous les serveurs utilisent encore cette configuration.' : 'Check every TLS endpoint of the domain. A retained or cached result does not prove that all servers still use this configuration.'),
  });
  for (const id of ids) detailedRuleGuidance.push({
    keys: [source === 'lighthouse' ? `lighthouse.audit.${id}` : id], verifiedAt: '2026-10-26',
    reference: reference ?? lighthouseCatalogue.audits[id as keyof typeof lighthouseCatalogue.audits] ?? 'https://developer.chrome.com/docs/lighthouse/overview',
    fr: copy(fr, true), en: copy(en, false),
  });
}

rule(['first-contentful-paint'],
  ['Le premier contenu tarde à apparaître', 'Une page qui reste vide retarde le début de lecture.', 'Dans Performance, repérer FCP, la réponse HTML et les styles ou polices attendus avant le premier texte ou la première image.', 'Réduire la phase réellement lente : réponse serveur, styles bloquants ou attente des polices. Différer les scripts non nécessaires au premier affichage.', 'Comparer FCP sur plusieurs chargements au même profil et vérifier que le premier écran apparaît sans contenu sans style.'],
  ['The first content appears late', 'A blank page delays the start of reading.', 'In Performance, locate FCP, the HTML response and styles or fonts awaited before the first text or image.', 'Reduce the slow phase: server response, blocking styles or font waiting. Defer scripts unnecessary for initial rendering.', 'Compare FCP over several loads with the same profile and check that the first screen appears without unstyled content.']);
rule(['speed-index'],
  ['Le contenu visible se remplit lentement', 'L’apparition progressive du premier écran peut prolonger l’attente, même si un premier élément est déjà visible.', 'Dans le film du chargement Lighthouse, repérer ce qui reste vide et retrouver ses ressources dans la cascade réseau.', 'Donner la priorité aux ressources du premier écran et différer les éléments hors écran. Réduire les images, styles ou scripts effectivement responsables du retard.', 'Comparer le film et le Speed Index au même format d’écran ; le contenu utile doit apparaître plus tôt sans régression visuelle.'],
  ['Visible content fills in slowly', 'Progressive filling of the first screen can prolong waiting even after one element appears.', 'In the Lighthouse loading filmstrip, locate blank areas and find their resources in the network waterfall.', 'Prioritise first-screen resources and defer offscreen content. Reduce the images, styles or scripts actually causing the delay.', 'Compare the filmstrip and Speed Index at the same viewport; useful content should appear earlier without visual regressions.']);
rule(['total-blocking-time', 'max-potential-fid'],
  ['Des tâches longues bloquent le navigateur', 'Le navigateur peut retarder les interactions pendant qu’il exécute une longue tâche ; cette mesure de laboratoire ne décrit pas toutes les interactions réelles.', 'Dans Performance, examiner les tâches longues du thread principal et leur pile d’appels, puis retrouver le module source.', 'Découper le travail JavaScript, différer les initialisations non indispensables et déplacer les calculs isolables dans un worker. Réduire le travail exécuté, pas seulement la taille du fichier.', 'Comparer le temps bloquant et les tâches longues avec le même profil ; tester les clics et la saisie pendant le chargement.'],
  ['Long tasks block the browser', 'The browser may delay interactions while executing a long task; this lab measurement does not describe every real interaction.', 'In Performance, inspect long main-thread tasks and their call stacks, then locate the source module.', 'Split JavaScript work, defer nonessential initialisation and move suitable isolated calculations to a worker. Reduce execution work, not only file size.', 'Compare blocking time and long tasks with the same profile; test clicks and typing during loading.']);
rule(['interaction-to-next-paint', 'inp-breakdown-insight'],
  ['La réponse aux interactions est lente', 'Une réponse visuelle tardive peut donner l’impression que le contrôle ne répond pas.', 'Enregistrer le clic ou la saisie signalés dans Performance et examiner attente avant traitement, gestionnaire et affichage suivant.', 'Réduire le travail de la phase lente : libérer le thread principal, raccourcir le gestionnaire ou limiter les changements de DOM. Afficher rapidement le retour de l’action.', 'Rejouer les interactions identifiées et comparer leurs phases ; la réponse visuelle arrive plus tôt et l’action aboutit. Une navigation sans interaction ne suffit pas à mesurer l’INP.'],
  ['Interaction response is slow', 'A delayed visual response can make a control appear unresponsive.', 'Record the flagged click or typing in Performance and inspect input delay, event processing and the next paint.', 'Reduce work in the slow phase: free the main thread, shorten the handler or limit DOM changes. Display feedback promptly.', 'Repeat the identified interactions and compare their phases; visual feedback arrives earlier and the action completes. Navigation without interaction is insufficient to measure INP.']);
rule(['interactive'],
  ['La page devient interactive tardivement', 'Le contenu peut être visible avant que le navigateur soit suffisamment disponible pour répondre.', 'Dans la trace de chargement, examiner les tâches longues et requêtes qui repoussent la période de disponibilité mesurée par TTI.', 'Différer les initialisations et requêtes non indispensables ; découper les tâches longues du code réellement exécuté au démarrage.', 'Tester les fonctions pendant le chargement et comparer TTI dans les mêmes conditions ; compléter cette ancienne métrique par les interactions réelles.'],
  ['The page becomes interactive late', 'Content may be visible before the browser is available to respond.', 'In the loading trace, inspect long tasks and requests delaying the availability period measured by TTI.', 'Defer nonessential initialisation and requests; split long tasks in code actually executed at startup.', 'Test features during loading and compare TTI under the same conditions; supplement this legacy metric with actual interactions.']);
rule(['server-response-time', 'document-latency-insight'],
  ['La réponse du document retarde le chargement', 'Le navigateur attend le document avant de découvrir une grande partie de ses ressources.', 'Dans Réseau, sélectionner le document principal et examiner redirections, attente de réponse et Content-Encoding. Corréler une attente serveur avec ses journaux.', 'Supprimer les détours de redirection et optimiser la génération ou le cache du HTML selon la phase mesurée. Activer la compression adaptée aux réponses textuelles sans mettre en cache publiquement du contenu privé.', 'Comparer la chronologie de la requête HTML au même profil et vérifier que le bon contenu est servi aux visiteurs connectés et anonymes.'],
  ['The document response delays loading', 'The browser waits for the document before discovering many of its resources.', 'In Network, select the main document and inspect redirects, response waiting and Content-Encoding. Correlate server waiting with server logs.', 'Remove redirect detours and optimise HTML generation or caching according to the measured phase. Enable suitable text compression without publicly caching private content.', 'Compare the HTML request timing with the same profile and verify the correct content for signed-in and anonymous visitors.']);
rule(['redirects'],
  ['Des redirections retardent l’arrivée sur la page', 'Chaque détour peut ajouter une attente avant le document final.', 'Dans Réseau, conserver le journal et reconstituer les réponses 3xx jusqu’à la destination finale.', 'Faire pointer liens et redirections vers la destination canonique finale ; regrouper les passages domaine, HTTPS et chemin quand leur logique le permet.', 'Tester les anciennes adresses : elles atteignent le contenu voulu sans boucle et avec moins de détours.'],
  ['Redirects delay arrival on the page', 'Each detour can add waiting before the final document.', 'In Network, preserve the log and trace 3xx responses to the final destination.', 'Point links and redirects to the final canonical destination; combine domain, HTTPS and path transitions where their logic allows.', 'Test old addresses: they reach the intended content without loops and with fewer detours.']);
rule(['bootup-time', 'mainthread-work-breakdown'],
  ['Le traitement au chargement mobilise le navigateur', 'Compiler ou exécuter les scripts et calculer le rendu peut retarder l’affichage et les interactions.', 'Dans Performance, trier Bottom-up par durée et distinguer scripts, calcul de styles et mise en page. Retrouver les fichiers et fonctions dominants.', 'Réduire les initialisations coûteuses, charger à la demande les fonctions secondaires et limiter les recalculs répétés. Pour un script tiers, réduire son usage ou sa fréquence de chargement.', 'Comparer la durée des postes dominants à profil identique, puis tester les fonctions dont l’initialisation a changé.'],
  ['Loading work occupies the browser', 'Compiling or executing scripts and calculating rendering can delay display and interactions.', 'In Performance, sort Bottom-up by duration and distinguish scripting, style calculation and layout. Locate dominant files and functions.', 'Reduce expensive initialisation, load secondary features on demand and limit repeated calculations. For third-party scripts, reduce their use or loading frequency.', 'Compare dominant work durations with the same profile, then test features whose initialisation changed.']);
rule(['layout-shifts'],
  ['Des éléments se déplacent pendant l’affichage', 'Un déplacement inattendu peut faire perdre la lecture ou provoquer un clic au mauvais endroit.', 'Dans Performance, sélectionner les événements Layout Shift et examiner les éléments déplacés ainsi que les insertions qui les précèdent.', 'Réserver l’espace des images et intégrations, stabiliser les polices et éviter d’insérer du contenu au-dessus du contenu déjà lu.', 'Rejouer un chargement lent et le parcours ; les éléments restent stables et les événements ciblés disparaissent ou diminuent.'],
  ['Elements move during rendering', 'Unexpected movement can disrupt reading or cause a click in the wrong place.', 'In Performance, select Layout Shift events and inspect shifted elements and preceding insertions.', 'Reserve image and embed space, stabilise fonts and avoid inserting content above material already being read.', 'Repeat a slow load and the journey; elements remain stable and targeted shift events disappear or decrease.']);
rule(['total-byte-weight'],
  ['La page transfère beaucoup de données', 'Un transfert important pénalise les connexions limitées et la consommation de données.', 'Dans Réseau, trier par taille transférée et retrouver les plus gros fichiers via leur initiateur.', 'Réduire les images et vidéos selon leur affichage, supprimer les dépendances inutiles et charger les contenus secondaires à la demande. Mesurer le transfert compressé réel.', 'Comparer les octets transférés à cache et parcours identiques, puis contrôler la qualité et les fonctions des ressources modifiées.'],
  ['The page transfers substantial data', 'Large transfers penalise limited connections and data consumption.', 'In Network, sort by transferred size and locate the largest files using their initiator.', 'Size images and videos for their display, remove unused dependencies and load secondary content on demand. Measure actual compressed transfer.', 'Compare transferred bytes with the same cache and journey, then check the quality and features of modified resources.']);
for (const [id, type] of [['unminified-css', 'CSS'], ['unminified-javascript', 'JavaScript']] as const) rule([id],
  [`Des fichiers ${type} peuvent être minifiés`, 'Des espaces, commentaires et constructions réductibles augmentent le transfert sans ajouter de fonction.', `Retrouver le fichier ${type} signalé dans Réseau et sa production dans la chaîne de build.`, `Activer la minification ${type} pour le build de production et servir cette version. Conserver les sources de développement et les licences requises.`, 'Comparer la taille transférée du fichier servi et tester affichage et interactions avec le build de production.'],
  [`Some ${type} files can be minified`, 'Whitespace, comments and reducible constructs increase transfer without adding functionality.', `Find the flagged ${type} file in Network and its production in the build pipeline.`, `Enable ${type} minification in the production build and serve that version. Retain development sources and required licences.`, 'Compare the served file’s transferred size and test rendering and interactions with the production build.']);
rule(['dom-size-insight'],
  ['La structure de la page coûte cher à traiter', 'Un DOM volumineux ou profond peut rendre les calculs de style et de mise en page plus coûteux.', 'Dans Elements et la trace Performance, identifier les sous-arbres signalés et les recalculs qui prennent du temps.', 'Réduire les conteneurs inutiles et ne rendre que les éléments nécessaires des longues listes. Préserver recherche, navigation clavier et contenu utile aux technologies d’assistance.', 'Comparer nombre de nœuds et durées de recalcul, puis tester défilement, recherche et accès clavier à tous les éléments.'],
  ['The page structure is costly to process', 'A large or deep DOM can make style and layout calculations more expensive.', 'In Elements and the Performance trace, identify flagged subtrees and expensive recalculations.', 'Reduce unnecessary wrappers and render only needed items in long lists. Preserve search, keyboard navigation and content useful to assistive technology.', 'Compare node counts and recalculation time, then test scrolling, search and keyboard access to all items.']);
rule(['duplicated-javascript-insight'],
  ['Du JavaScript est livré plusieurs fois', 'Des modules dupliqués augmentent le téléchargement et peuvent répéter le travail du navigateur.', 'Retrouver les paquets et fichiers signalés dans le diagnostic et l’analyse des bundles du build.', 'Aligner les versions compatibles des dépendances, dédupliquer leur résolution et partager les modules communs entre points d’entrée sans créer un bundle global inutile.', 'Inspecter le build produit : les copies ciblées disparaissent. Tester les pages et fonctions qui partageaient ces dépendances.'],
  ['JavaScript is delivered more than once', 'Duplicated modules increase downloads and can repeat browser work.', 'Locate flagged packages and files in the diagnosis and the build’s bundle analysis.', 'Align compatible dependency versions, deduplicate their resolution and share common modules between entry points without creating an unnecessary global bundle.', 'Inspect the production build: targeted copies disappear. Test pages and features that shared these dependencies.']);
rule(['forced-reflow-insight'],
  ['Le code force des recalculs de mise en page', 'Lire la géométrie après une modification du DOM peut obliger le navigateur à recalculer immédiatement la mise en page.', 'Dans Performance, ouvrir Forced reflow et suivre la pile d’appels jusqu’aux lectures telles que offsetWidth ou getBoundingClientRect.', 'Regrouper les lectures de géométrie avant les écritures de styles et réutiliser les mesures valides. Éviter les alternances lecture/écriture dans les boucles.', 'Rejouer le geste déclencheur : les recalculs forcés ciblés diminuent et la position des éléments reste correcte.'],
  ['Code forces layout recalculation', 'Reading geometry after a DOM change can force the browser to recalculate layout immediately.', 'In Performance, open Forced reflow and follow the call stack to reads such as offsetWidth or getBoundingClientRect.', 'Batch geometry reads before style writes and reuse valid measurements. Avoid alternating reads and writes inside loops.', 'Repeat the triggering gesture: targeted forced recalculations decrease and element positioning remains correct.']);
rule(['legacy-javascript-insight'],
  ['Du code de compatibilité ancien alourdit les scripts', 'Des transformations et polyfills inutiles aux navigateurs visés augmentent le code téléchargé et traité.', 'Retrouver les polyfills ou transformations signalés, leur paquet et la configuration de compatibilité du build.', 'Mettre à jour les cibles de compilation selon les navigateurs réellement supportés ; retirer uniquement les polyfills devenus inutiles et actualiser les dépendances qui les embarquent.', 'Comparer le bundle livré et tester les navigateurs encore supportés, y compris les API couvertes auparavant par les polyfills.'],
  ['Legacy compatibility code increases script size', 'Transforms and polyfills unnecessary for target browsers increase downloaded and processed code.', 'Locate flagged polyfills or transforms, their package and the build compatibility configuration.', 'Update compilation targets to browsers actually supported; remove only unnecessary polyfills and update dependencies bundling them.', 'Compare the delivered bundle and test supported browsers, including APIs previously covered by polyfills.']);
rule(['modern-http-insight'],
  ['Certaines ressources utilisent un ancien protocole HTTP', 'Des connexions HTTP anciennes peuvent limiter le partage des requêtes sur une même connexion.', 'Afficher la colonne Protocol de Réseau pour les ressources signalées et identifier le serveur ou CDN qui termine TLS.', 'Activer HTTP/2 ou HTTP/3 sur le point de terminaison maîtrisé avec TLS et ALPN adaptés. Pour un fournisseur tiers, lui transmettre le diagnostic ou évaluer une alternative.', 'Recharger avec un client compatible et vérifier le protocole négocié pour chaque origine ciblée ; comparer la cascade sans promettre un gain fixe.'],
  ['Some resources use an older HTTP protocol', 'Older HTTP connections may limit request sharing over a single connection.', 'Show Network’s Protocol column for flagged resources and identify the server or CDN terminating TLS.', 'Enable HTTP/2 or HTTP/3 on an endpoint you control with suitable TLS and ALPN. For a third-party provider, share the diagnosis or assess an alternative.', 'Reload with a compatible client and check the protocol negotiated for each target origin; compare the waterfall without assuming a fixed gain.']);
rule(['network-dependency-tree-insight'],
  ['Une chaîne de ressources retarde le contenu', 'Des fichiers découverts les uns après les autres peuvent prolonger le chemin nécessaire à l’affichage.', 'Dans l’arbre des dépendances réseau, suivre la chaîne critique et les initiateurs de chaque requête.', 'Rendre les ressources essentielles découvrables plus tôt dans le HTML, raccourcir les importations en cascade et différer les dépendances secondaires. Précharger uniquement une ressource critique confirmée.', 'Comparer début et fin de la chaîne à profil identique et vérifier qu’aucun téléchargement prioritaire inutile n’a été ajouté.'],
  ['A resource chain delays content', 'Files discovered one after another can extend the path required for rendering.', 'In the network dependency tree, follow the critical chain and each request’s initiator.', 'Make essential resources discoverable earlier in HTML, shorten cascading imports and defer secondary dependencies. Preload only a confirmed critical resource.', 'Compare the chain’s start and end with the same profile and check that no unnecessary priority download was added.']);
rule(['third-parties-insight'],
  ['Des services tiers pèsent sur le chargement', 'Des intégrations externes peuvent ajouter des transferts et du travail sur le thread principal.', 'Dans le diagnostic tiers, identifier le fournisseur, les ressources et le temps de traitement ; retrouver le tag ou composant qui les charge.', 'Retirer les intégrations sans usage, éviter les doubles installations et charger les fonctions secondaires au moment utile. Conserver le consentement et les fonctions indispensables.', 'Comparer transfert et travail du fournisseur puis tester les parcours, mesures et consentements qui dépendent de l’intégration.'],
  ['Third-party services add loading work', 'External integrations may add transfer and main-thread work.', 'In the third-party diagnosis, identify the provider, resources and processing time; locate the loading tag or component.', 'Remove unused integrations, avoid duplicate installations and load secondary features when needed. Preserve consent and essential functions.', 'Compare the provider’s transfer and processing work, then test journeys, measurements and consent depending on the integration.']);
rule(['viewport-insight'],
  ['La configuration mobile peut retarder les appuis', 'Une déclaration viewport inadaptée peut empêcher le navigateur de traiter rapidement les appuis tactiles.', 'Dans le head du document, examiner meta name="viewport" et reproduire un appui sur mobile.', 'Déclarer width=device-width et une échelle initiale adaptée ; corriger les mises en page trop larges sans interdire le zoom utilisateur.', 'Vérifier la réponse aux appuis, l’absence de débordement à petite largeur et la possibilité de zoomer.'],
  ['Mobile configuration can delay taps', 'An unsuitable viewport declaration can prevent the browser from processing taps promptly.', 'In the document head, inspect meta name="viewport" and reproduce a tap on mobile.', 'Declare width=device-width and a suitable initial scale; fix overly wide layouts without disabling user zoom.', 'Check tap response, absence of narrow-screen overflow and the ability to zoom.']);

// Accessibility: inspect the actual node and change the component producing it.
const nodeFr = 'Dans Éléments, retrouver le sélecteur signalé, examiner le DOM et le nom/rôle dans Accessibilité, puis ouvrir le composant qui le produit.';
const nodeEn = 'In Elements, locate the flagged selector, inspect the DOM and name/role in Accessibility, then open the component producing it.';
function a11y(ids: string[], fr: [string, string, string, string], en: [string, string, string, string]) {
  rule(ids, [fr[0], fr[1], nodeFr, fr[2], fr[3]], [en[0], en[1], nodeEn, en[2], en[3]]);
}
a11y(['link-name'],
  ['Un lien n’a pas de nom accessible', 'Un lien sans nom ne permet pas de comprendre sa destination avec un lecteur d’écran.', 'Dans le lien signalé, ajouter un texte décrivant la destination. Si le lien contient seulement une image, renseigner son alt avec cette destination ; pour une icône seule, donner un nom accessible adapté. Ne pas ajouter un label de champ à un lien.', 'Dans l’arbre d’accessibilité, le lien annonce sa destination ; l’activer au clavier et vérifier qu’il ouvre le contenu attendu.'],
  ['A link has no accessible name', 'A nameless link prevents screen-reader users from understanding its destination.', 'Add text describing the destination inside the flagged link. For an image-only link, use the image alt to describe that destination; give an icon-only link a suitable accessible name. Do not add a form-field label to a link.', 'In the accessibility tree, the link announces its destination; activate it by keyboard and check that it opens the expected content.']);
a11y(['select-name'],
  ['Une liste de choix n’a pas de nom accessible', 'La sélection initiale ne remplace pas le nom du champ : son objectif doit rester compréhensible après un changement de valeur.', 'Ajouter un label visible décrivant le choix, avec for correspondant à l’id unique du select signalé. Vérifier que les attributs ARIA existants ne remplacent pas ce nom par un texte vide ou différent.', 'Dans l’arbre d’accessibilité, le select annonce le libellé et la valeur séparément ; changer de choix au clavier puis vérifier le comportement.'],
  ['A select has no accessible name', 'The initial option is not the field name: its purpose must remain clear after choosing another value.', 'Add a visible label describing the choice, with for matching the flagged select’s unique id. Check that existing ARIA attributes do not override it with an empty or different name.', 'In the accessibility tree, the select announces its label and value separately; change the option by keyboard and verify the behaviour.']);
const roles = [
  ['aria-command-name', 'commande', 'command'], ['aria-dialog-name', 'boîte de dialogue', 'dialog'],
  ['aria-input-field-name', 'champ ARIA', 'ARIA input'], ['aria-meter-name', 'jauge', 'meter'],
  ['aria-progressbar-name', 'barre de progression', 'progress bar'], ['aria-toggle-field-name', 'contrôle à état', 'toggle'],
  ['aria-tooltip-name', 'infobulle', 'tooltip'], ['aria-treeitem-name', 'élément d’arbre', 'tree item'],
] as const;
a11y(['svg-img-alt'],
  ['Une image SVG n’a pas de nom accessible', 'Une illustration SVG porteuse d’information peut perdre son sens en lecture assistée.', 'Pour un SVG informatif, fournir un title relié par aria-labelledby à un identifiant unique, ou un aria-label adapté. Pour un SVG purement décoratif, le masquer aux technologies d’assistance sans masquer le contrôle parent.', 'Le SVG informatif possède un nom utile dans Accessibility ; une icône de bouton laisse le nom et le rôle du bouton accessibles.'],
  ['An SVG image has no accessible name', 'An informative SVG illustration may lose its meaning in assisted reading.', 'For an informative SVG, provide a title linked with aria-labelledby to a unique ID, or a suitable aria-label. Hide purely decorative SVGs from assistive technology without hiding the parent control.', 'The informative SVG has a useful name in Accessibility; a button icon leaves the button’s name and role accessible.']);
a11y(['input-image-alt'],
  ['Un bouton image n’a pas de nom accessible', 'Un input de type image doit expliquer l’action qu’il déclenche, pas seulement l’image affichée.', 'Renseigner alt sur input type="image" avec l’action du bouton, par exemple « Rechercher ». Vérifier qu’un attribut ARIA ne remplace pas ce nom par un texte incohérent.', 'Le nom calculé annonce l’action attendue ; le bouton fonctionne au clavier et avec un lecteur d’écran.'],
  ['An image button has no accessible name', 'An image input must explain the action it triggers, not merely describe its picture.', 'Set alt on input type="image" to the button action, for example “Search”. Check that an ARIA attribute does not replace this with conflicting text.', 'The computed name announces the intended action; the button works by keyboard and with a screen reader.']);
for (const [id, frRole, enRole] of roles) a11y([id],
  [`Le nom accessible d’un élément « ${frRole} » manque`, 'Sans nom accessible, un lecteur d’écran ne peut pas expliquer la fonction de cet élément.', 'Associer le texte visible pertinent avec aria-labelledby et des identifiants existants et uniques ; utiliser aria-label si aucun texte visible ne peut nommer le contrôle. Ne pas remplacer un rôle pour faire disparaître l’alerte.', 'Dans Accessibility, le nom calculé décrit la fonction. Vérifier son annonce avec un lecteur d’écran dans les états ouverts, fermés ou modifiés.'],
  [`An accessible name is missing for a ${enRole}`, 'Without an accessible name, a screen reader cannot explain this element’s purpose.', 'Associate relevant visible text using aria-labelledby and existing unique IDs; use aria-label when no visible text can name the control. Do not replace the role merely to clear the alert.', 'In Accessibility, the computed name describes the purpose. Check its screen-reader announcement in opened, closed or changed states.']);
a11y(['aria-allowed-attr', 'aria-prohibited-attr'],
  ['Un attribut ARIA ne convient pas au rôle', 'Un attribut non autorisé ou interdit sur ce rôle peut être ignoré ou produire une annonce incorrecte.', 'Comparer chaque attribut signalé aux propriétés du rôle effectif. Retirer l’attribut incompatible ou utiliser l’élément HTML et le rôle correspondant réellement à la fonction.', 'Le rôle et les états calculés correspondent au comportement ; tester clavier et annonce après changement.'],
  ['An ARIA attribute does not match its role', 'An unsupported or prohibited attribute can be ignored or announced incorrectly.', 'Compare flagged attributes with the effective role’s properties. Remove incompatible attributes or use the HTML element and role matching the actual function.', 'Computed role and states match behaviour; test keyboard use and announcements after changing them.']);
a11y(['aria-conditional-attr'],
  ['Une condition d’utilisation d’ARIA manque', 'Certains attributs ARIA ne sont valides que pour certains états ou types de contrôles.', 'Lire la condition de la règle signalée puis ajuster ensemble le rôle, le type natif et l’attribut concerné. Éviter d’ajouter des états que le contrôle ne possède pas.', 'Tester chaque état du contrôle ; l’attribut reste cohérent avec son rôle et sa valeur réelle.'],
  ['An ARIA usage condition is missing', 'Some ARIA attributes are valid only for particular states or control types.', 'Read the flagged rule’s condition and adjust the role, native type and attribute together. Avoid adding states the control does not have.', 'Test each control state; the attribute remains consistent with its role and actual value.']);
a11y(['aria-deprecated-role', 'aria-roles'],
  ['Un rôle ARIA est invalide ou obsolète', 'Un rôle non reconnu peut empêcher la technologie d’assistance de comprendre l’élément.', 'Corriger l’orthographe du rôle ou remplacer le rôle obsolète par un élément HTML natif adapté. Pour un composant personnalisé, implémenter aussi les comportements clavier du rôle choisi.', 'Le rôle attendu apparaît dans l’arbre d’accessibilité et les interactions clavier fonctionnent.'],
  ['An ARIA role is invalid or deprecated', 'An unrecognised role can prevent assistive technology from understanding the element.', 'Correct the role spelling or replace a deprecated role with suitable native HTML. For custom controls, implement the chosen role’s keyboard behaviour too.', 'The expected role appears in the accessibility tree and keyboard interactions work.']);
a11y(['aria-required-attr'],
  ['Un état ARIA obligatoire manque', 'Le rôle est incomplet sans ses propriétés obligatoires, par exemple la valeur d’un curseur.', 'Ajouter les propriétés obligatoires du rôle signalé avec des valeurs correspondant à l’état réel et les mettre à jour lors des interactions.', 'Les propriétés requises sont présentes, valides et annoncées lorsque l’état change.'],
  ['A required ARIA state is missing', 'The role is incomplete without required properties, such as a slider’s value.', 'Add the flagged role’s required properties with values matching actual state and update them during interaction.', 'Required properties are present, valid and announced when state changes.']);
a11y(['aria-required-children', 'aria-required-parent'],
  ['La structure d’un composant ARIA est incomplète', 'Un rôle privé de son parent ou de ses enfants requis peut perdre ses relations dans la lecture assistée.', 'Rétablir la relation requise entre les rôles, par exemple listbox et option. Vérifier les portails et contenus conditionnels avant d’ajouter aria-owns ; préférer une structure DOM cohérente.', 'Ouvrir et fermer le composant : parents, enfants, sélection et navigation restent cohérents dans l’arbre d’accessibilité.'],
  ['An ARIA component structure is incomplete', 'A role missing its required parent or children may lose relationships in assisted reading.', 'Restore the required relationship between roles, such as listbox and option. Check portals and conditional content before adding aria-owns; prefer a coherent DOM structure.', 'Open and close the component: parents, children, selection and navigation remain coherent in the accessibility tree.']);
a11y(['aria-valid-attr', 'aria-valid-attr-value'],
  ['Un attribut ARIA ou sa valeur est invalide', 'Une faute de nom, une valeur non autorisée ou une référence inexistante peut rendre l’état inaccessible.', 'Corriger le nom et la valeur de l’attribut selon sa définition. Pour une référence d’identifiant, vérifier que la cible existe, est unique et porte le contenu attendu.', 'Inspecter les propriétés calculées dans tous les états ; elles reflètent les valeurs réelles sans référence cassée.'],
  ['An ARIA attribute or value is invalid', 'A misspelled name, unsupported value or missing reference may make state inaccessible.', 'Correct the attribute name and value according to its definition. For an ID reference, check that the target exists, is unique and contains the intended content.', 'Inspect computed properties in all states; they reflect actual values without broken references.']);
a11y(['aria-hidden-body'],
  ['Le corps de la page est masqué aux lecteurs d’écran', 'aria-hidden sur body peut retirer toute la page de l’arbre d’accessibilité.', 'Retirer aria-hidden de body. Pour une modale, masquer uniquement les régions d’arrière-plan adaptées et gérer le focus dans la modale.', 'La page et la modale restent lisibles au lecteur d’écran ; le focus revient au déclencheur à la fermeture.'],
  ['The page body is hidden from screen readers', 'aria-hidden on body can remove the whole page from the accessibility tree.', 'Remove aria-hidden from body. For a modal, hide only appropriate background regions and manage focus inside the modal.', 'The page and modal remain readable by screen readers; focus returns to the trigger when closed.']);
a11y(['aria-hidden-focus'],
  ['Un élément masqué reçoit encore le focus', 'Un utilisateur clavier peut atteindre un contrôle que le lecteur d’écran ne voit pas.', 'Si le contrôle doit être utilisable, retirer le masquage ARIA de ses ancêtres. Sinon, retirer toute la région du parcours clavier, par exemple avec inert, et gérer le focus lors de son ouverture.', 'Parcourir la page avec Tab dans chaque état : aucun focus n’entre dans un contenu masqué.'],
  ['A hidden element still receives focus', 'Keyboard users can reach a control that the screen reader cannot see.', 'If the control should be usable, remove ARIA hiding from its ancestors. Otherwise remove the entire region from keyboard navigation, for example with inert, and manage focus when it opens.', 'Tab through the page in every state: focus never enters hidden content.']);
a11y(['aria-text'],
  ['Un rôle texte masque des éléments interactifs', 'role="text" peut supprimer les rôles de ses descendants et rendre des contrôles incompréhensibles.', 'Retirer role="text" du conteneur qui comprend un lien ou un contrôle ; limiter son usage éventuel à du texte sans interaction.', 'Les liens et boutons descendants retrouvent leur rôle, leur nom et leur fonctionnement au clavier.'],
  ['A text role hides interactive semantics', 'role="text" can remove descendant roles and make controls incomprehensible.', 'Remove role="text" from containers containing links or controls; restrict any use to noninteractive text.', 'Descendant links and buttons regain their roles, names and keyboard operation.']);
a11y(['presentation-role-conflict'],
  ['Un rôle de présentation contredit le comportement', 'Un élément interactif ou porteur d’états ARIA ne peut pas être traité comme pure décoration.', 'Retirer role="presentation" ou role="none" d’un élément fonctionnel. Pour une vraie décoration, supprimer les attributs et comportements interactifs qui lui donnent une fonction.', 'L’arbre d’accessibilité expose les éléments utiles et ignore uniquement les décorations sans interaction.'],
  ['A presentation role conflicts with behaviour', 'An interactive element or one with ARIA states cannot be treated as pure decoration.', 'Remove role="presentation" or role="none" from functional elements. For true decoration, remove attributes and interactive behaviour giving it a function.', 'The accessibility tree exposes useful elements and ignores only noninteractive decoration.']);
a11y(['accesskeys'],
  ['Des raccourcis accesskey sont dupliqués', 'Plusieurs éléments partageant un raccourci peuvent rendre son action imprévisible.', 'Supprimer les accesskey inutiles ou attribuer des valeurs uniques sur toute la page, en tenant compte des raccourcis du navigateur et des technologies d’assistance.', 'Tester chaque raccourci conservé : il atteint un seul contrôle attendu sans conflit sur les environnements supportés.'],
  ['Accesskey shortcuts are duplicated', 'Several elements sharing a shortcut can make its action unpredictable.', 'Remove unnecessary accesskeys or assign unique values across the page, accounting for browser and assistive technology shortcuts.', 'Test each retained shortcut: it reaches one intended control without conflicts in supported environments.']);
a11y(['definition-list', 'dlitem'],
  ['Une liste de définitions est mal structurée', 'Des termes et définitions hors de leur structure peuvent perdre leur association en lecture assistée.', 'Placer les termes dt et descriptions dd dans un dl, avec les groupements autorisés. Retirer les conteneurs qui cassent la relation ou utiliser une liste ordinaire si le contenu ne définit pas des termes.', 'La liste expose les termes avec leurs descriptions dans le DOM et au lecteur d’écran.'],
  ['A definition list is incorrectly structured', 'Terms and definitions outside their structure may lose their association in assisted reading.', 'Place dt terms and dd descriptions inside a dl using allowed groupings. Remove wrappers breaking the relationship or use a normal list for content that does not define terms.', 'The list exposes terms with their descriptions in the DOM and screen reader.']);
a11y(['list', 'listitem'],
  ['Une liste contient des relations HTML invalides', 'Des éléments li isolés ou des enfants inadaptés peuvent empêcher l’annonce correcte de la liste.', 'Placer les li sous ul, ol ou menu selon le contenu et garder les autres éléments dans les li. Corriger le composant ou la boucle de rendu qui produit la structure.', 'Le lecteur d’écran annonce la liste et ses éléments dans le bon ordre.'],
  ['A list has invalid HTML relationships', 'Isolated li elements or unsuitable children can prevent correct list announcements.', 'Place li under ul, ol or menu as appropriate and keep other content inside li. Fix the component or rendering loop producing the structure.', 'The screen reader announces the list and its items in the correct order.']);
a11y(['document-title'],
  ['Le document rendu n’a pas de titre utile', 'Sans titre, la page est difficile à reconnaître dans un onglet ou un lecteur d’écran.', 'Renseigner un title non vide décrivant cette page dans le head ; vérifier aussi sa mise à jour après une navigation côté client.', 'Le titre de l’onglet et le DOM rendu identifient la page courante après chargement et navigation.'],
  ['The rendered document lacks a useful title', 'Without a title, the page is difficult to recognise in a tab or screen reader.', 'Set a nonempty page-specific title in head; also update it after client-side navigation.', 'The tab title and rendered DOM identify the current page after loading and navigation.']);
a11y(['frame-title'],
  ['Un cadre intégré n’est pas nommé', 'Un iframe sans nom clair rend sa fonction difficile à identifier en lecture assistée.', 'Donner à chaque iframe concerné un attribut title décrivant son contenu ou sa fonction ; différencier les cadres dont les fonctions diffèrent.', 'Le lecteur d’écran annonce un nom utile avant d’entrer dans le contenu intégré.'],
  ['An embedded frame is unnamed', 'An iframe without a clear name makes its purpose difficult to identify in assisted reading.', 'Give each affected iframe a title attribute describing its content or purpose; distinguish frames with different functions.', 'The screen reader announces a useful name before entering embedded content.']);
a11y(['html-xml-lang-mismatch', 'valid-lang'],
  ['Des déclarations de langue sont incohérentes', 'Une langue invalide ou contradictoire peut provoquer une mauvaise prononciation.', 'Utiliser un code de langue valide correspondant au texte. Aligner lang et xml:lang lorsqu’ils coexistent ; marquer séparément les passages dans une autre langue.', 'Les attributs sont valides et cohérents ; écouter la prononciation des passages concernés au lecteur d’écran.'],
  ['Language declarations are inconsistent', 'Invalid or conflicting language declarations can cause incorrect pronunciation.', 'Use a valid language tag matching the text. Align lang and xml:lang when both exist; mark passages in another language separately.', 'Attributes are valid and consistent; listen to affected passages with a screen reader.']);
a11y(['label-content-name-mismatch'],
  ['Le nom accessible ne reprend pas le texte visible', 'La commande vocale peut échouer si le nom du contrôle ne contient pas son libellé visible.', 'Faire commencer le nom accessible par le texte visible ou retirer un aria-label qui le remplace inutilement. Préserver le complément utile sans changer le sens.', 'Comparer texte visible et nom calculé, puis activer le contrôle par son libellé avec une commande vocale si disponible.'],
  ['The accessible name omits visible text', 'Voice control may fail when a control’s name does not contain its visible label.', 'Start the accessible name with the visible text or remove an aria-label that unnecessarily replaces it. Preserve useful extra context without changing meaning.', 'Compare visible text and computed name, then activate the control by its label using voice control where available.']);
a11y(['landmark-one-main'],
  ['La région principale de la page est ambiguë', 'Sans région principale unique, la navigation par régions peut manquer de repère.', 'Entourer le contenu principal avec un seul main visible dans cet état de page ; sortir navigation et éléments répétés de cette région.', 'Dans l’arbre d’accessibilité, une seule région principale visible mène au contenu propre à la page.'],
  ['The page’s main region is ambiguous', 'Without a unique main region, landmark navigation may lack a clear destination.', 'Wrap primary content in one visible main for this page state; keep navigation and repeated elements outside it.', 'The accessibility tree contains one visible main region leading to page-specific content.']);
a11y(['link-in-text-block'],
  ['Un lien se distingue uniquement par sa couleur', 'Le lien peut être difficile à repérer pour une personne qui distingue mal les couleurs.', 'Ajouter un soulignement ou un autre indice visuel permanent aux liens du paragraphe ; vérifier aussi le contraste et les états survol/focus.', 'Le lien se distingue du texte voisin même sans perception de sa couleur et garde un focus visible.'],
  ['A link is distinguished only by colour', 'The link may be difficult to locate for people who cannot distinguish its colour.', 'Add underlining or another persistent visual cue to paragraph links; also check contrast and hover/focus states.', 'The link is distinguishable from surrounding text without relying on colour and retains visible focus.']);
a11y(['meta-refresh'],
  ['La page impose un rafraîchissement automatique', 'Un rafraîchissement temporisé peut interrompre la lecture ou la saisie.', 'Retirer meta http-equiv="refresh" pour les mises à jour automatiques ; proposer un contrôle utilisateur. Pour une redirection permanente, configurer la réponse HTTP appropriée.', 'La page ne se recharge plus pendant la lecture ou la saisie ; toute redirection voulue arrive à la bonne destination.'],
  ['The page forces an automatic refresh', 'A timed refresh can interrupt reading or typing.', 'Remove meta http-equiv="refresh" for automatic updates; provide a user control. For a permanent redirect, configure the appropriate HTTP response.', 'The page no longer reloads during reading or typing; any intended redirect reaches the correct destination.']);
a11y(['object-alt'],
  ['Un objet intégré n’a pas d’alternative accessible', 'Le sens d’un contenu object peut être perdu lorsque l’objet ne peut pas être perçu.', 'Ajouter dans object une alternative textuelle ou un lien vers une version équivalente ; nommer l’objet lorsque nécessaire sans substituer le nom à toute l’information.', 'Le contenu reste compréhensible lorsque l’objet ne charge pas et avec un lecteur d’écran.'],
  ['An embedded object lacks an accessible alternative', 'The meaning of object content may be lost when the object cannot be perceived.', 'Add a text alternative or link to an equivalent version inside object; name it where needed without substituting a name for all its information.', 'The content remains understandable when the object fails to load and with a screen reader.']);
a11y(['skip-link'],
  ['Le lien d’évitement n’atteint pas sa cible', 'Un lien pour aller au contenu ne sert pas si sa destination est absente ou ne reçoit pas correctement le focus.', 'Faire pointer href vers l’identifiant unique du contenu principal. Rendre la cible focalisable si nécessaire avec tabindex="-1" et afficher le lien lorsqu’il reçoit le focus.', 'Depuis le début de page, activer le lien au clavier : le focus et la prochaine tabulation arrivent au contenu principal.'],
  ['The skip link does not reach its target', 'A skip-to-content link is ineffective if its destination is missing or does not correctly receive focus.', 'Point href to the main content’s unique ID. Make the target focusable if needed with tabindex="-1" and display the link when focused.', 'From the start of the page, activate the link by keyboard: focus and the next Tab reach the main content.']);
a11y(['tabindex'],
  ['L’ordre clavier est forcé par tabindex', 'Un tabindex positif peut créer un ordre de navigation sans rapport avec le contenu visible.', 'Supprimer les tabindex positifs et organiser le DOM dans l’ordre logique. Utiliser les éléments natifs, tabindex="0" pour une entrée nécessaire et "-1" pour un focus programmatique.', 'Parcourir la page avec Tab et Maj+Tab : l’ordre reste logique, visible et complet.'],
  ['Tabindex forces keyboard order', 'A positive tabindex can create navigation order unrelated to visible content.', 'Remove positive tabindex values and put the DOM in logical order. Use native elements, tabindex="0" for a necessary entry and "-1" for programmatic focus.', 'Navigate with Tab and Shift+Tab: order remains logical, visible and complete.']);
a11y(['target-size'],
  ['Des cibles tactiles sont trop petites ou rapprochées', 'Un appui peut manquer le contrôle ou activer son voisin.', 'Agrandir la zone interactive réelle ou l’espacement entre les contrôles signalés, selon les dimensions et exceptions de la règle ; ne pas agrandir uniquement leur dessin.', 'Tester les cibles proches sur mobile et au zoom : chaque action se déclenche sans activer le voisin.'],
  ['Touch targets are too small or close together', 'A tap may miss its control or activate a neighbour.', 'Enlarge the actual interactive area or spacing of flagged controls according to the rule’s dimensions and exceptions; do not enlarge only their artwork.', 'Test nearby targets on mobile and with zoom: each action activates without triggering its neighbour.']);
a11y(['table-fake-caption'],
  ['Le titre d’un tableau n’est pas associé au tableau', 'Une cellule mise en forme comme un titre peut ne pas être reconnue comme sa légende.', 'Remplacer la fausse ligne de titre par un caption dans table ; conserver des cellules th pour les véritables en-têtes de colonnes ou lignes.', 'Le lecteur d’écran annonce le titre comme légende du tableau et conserve les associations d’en-têtes.'],
  ['A table title is not associated with the table', 'A cell styled as a title may not be recognised as its caption.', 'Replace the fake title row with a caption inside table; retain th cells for actual column or row headers.', 'The screen reader announces the title as the table caption and preserves header associations.']);
a11y(['td-has-header', 'td-headers-attr'],
  ['Les cellules d’un tableau perdent leurs en-têtes', 'Sans association fiable, une valeur peut être lue sans le contexte de sa ligne ou de sa colonne.', 'Utiliser th et scope pour les tableaux simples. Pour les relations complexes, faire référencer par headers les identifiants uniques des th correspondants dans le même tableau.', 'Parcourir chaque zone du tableau au lecteur d’écran : les valeurs sont annoncées avec les bons en-têtes.'],
  ['Table cells lose their headers', 'Without reliable associations, values may be read without row or column context.', 'Use th and scope for simple tables. For complex relationships, make headers reference the unique IDs of the corresponding th cells in the same table.', 'Navigate each table region with a screen reader: values are announced with the correct headers.']);
a11y(['autocomplete-valid'],
  ['Un champ déclare une autocomplétion invalide', 'Une valeur autocomplete incorrecte peut empêcher de reconnaître et remplir le champ.', 'Choisir les jetons autocomplete correspondant au contenu demandé et au type de champ, dans l’ordre prévu par HTML ; éviter les libellés libres inventés.', 'Tester un remplissage automatique : les données arrivent dans les bons champs et restent modifiables.'],
  ['A field declares invalid autocomplete', 'An incorrect autocomplete value can prevent the field from being recognised and filled.', 'Choose autocomplete tokens matching the requested information and input type, in the order defined by HTML; avoid invented free-form labels.', 'Test autofill: data lands in the correct fields and remains editable.']);

rule(['image-aspect-ratio'],
  ['Une image est déformée à l’affichage', 'Un rapport largeur/hauteur incorrect peut étirer ou écraser le contenu.', 'Dans Elements, comparer les dimensions intrinsèques de l’image aux dimensions CSS calculées dans les états signalés.', 'Préserver le rapport d’image avec une dimension automatique ou un cadre et object-fit adaptés. Distinguer recadrage volontaire et déformation.', 'Tester les largeurs d’écran ciblées : l’image garde ses proportions et le recadrage ne supprime pas l’information utile.'],
  ['An image is distorted when displayed', 'An incorrect width-to-height ratio can stretch or squash content.', 'In Elements, compare the image’s intrinsic dimensions with computed CSS dimensions in flagged states.', 'Preserve the aspect ratio with an automatic dimension or a suitable frame and object-fit. Distinguish intentional cropping from distortion.', 'Test target viewport widths: the image retains its proportions and cropping does not remove useful information.']);
rule(['image-size-responsive'],
  ['Une image manque de définition pour son affichage', 'Une image trop petite pour sa taille affichée et la densité d’écran peut paraître floue.', 'Comparer dimensions intrinsèques, taille affichée et devicePixelRatio de l’image signalée ; vérifier le fichier réellement choisi dans Réseau.', 'Fournir des variantes suffisamment définies via srcset et sizes, ou réduire la taille d’affichage. Ne pas augmenter seulement les dimensions CSS du même fichier.', 'Sur les densités et largeurs visées, vérifier netteté et fichier sélectionné sans livrer inutilement la plus grande version à tous.'],
  ['An image lacks resolution for its display', 'An image too small for its display size and screen density may look blurry.', 'Compare intrinsic dimensions, display size and devicePixelRatio for the flagged image; check the file actually selected in Network.', 'Provide sufficiently detailed variants with srcset and sizes, or reduce display size. Do not merely increase CSS dimensions for the same file.', 'At target densities and widths, check sharpness and selected file without unnecessarily serving the largest version to everyone.']);
rule(['is-on-https'],
  ['La page ou ses ressources utilisent HTTP', 'Du contenu HTTP peut être intercepté, modifié ou bloqué lorsqu’il est intégré dans une page HTTPS.', 'Dans Security et Réseau, retrouver le document ou les ressources HTTP signalées et leur initiateur.', 'Servir le document et ses dépendances en HTTPS avec un certificat valide ; corriger les URL HTTP dans les gabarits et intégrations, ou remplacer la ressource non sécurisée.', 'La page et les ressources chargent en HTTPS sans erreur de certificat ni avertissement de contenu mixte.'],
  ['The page or its resources use HTTP', 'HTTP content can be intercepted, modified or blocked when embedded in an HTTPS page.', 'In Security and Network, locate the flagged HTTP document or resources and their initiator.', 'Serve the document and dependencies over HTTPS with a valid certificate; fix HTTP URLs in templates and integrations or replace the insecure resource.', 'The page and resources load over HTTPS without certificate errors or mixed-content warnings.']);
rule(['redirects-http'],
  ['L’adresse HTTP ne redirige pas vers HTTPS', 'Un visiteur peut rester sur une connexion non chiffrée en suivant un ancien lien.', 'Ouvrir la variante HTTP de l’adresse et lire la chaîne de redirections dans Réseau, puis vérifier le certificat de la destination HTTPS.', 'Configurer au serveur ou CDN une redirection permanente vers la même ressource en HTTPS, avec conservation du chemin utile.', 'Les URL HTTP testées atteignent la bonne page HTTPS sans boucle et sans erreur de certificat.'],
  ['The HTTP address does not redirect to HTTPS', 'Visitors may remain on an unencrypted connection when following an old link.', 'Open the address’s HTTP variant and inspect the Network redirect chain, then check the HTTPS destination’s certificate.', 'Configure a permanent server or CDN redirect to the same resource over HTTPS, preserving the relevant path.', 'Tested HTTP URLs reach the correct HTTPS page without loops or certificate errors.']);
for (const [id, frName, enName, api] of [
  ['geolocation-on-start', 'géolocalisation', 'geolocation', 'navigator.geolocation'],
  ['notification-on-start', 'notification', 'notification', 'Notification.requestPermission'],
] as const) rule([id],
  [`La permission de ${frName} est demandée trop tôt`, 'Une demande au chargement, sans contexte, empêche de comprendre pourquoi cette permission est utile.', `Dans le code de démarrage, retrouver l’appel à ${api} et le composant qui le déclenche.`, 'Déplacer la demande après une action explicite associée à la fonction ; expliquer son usage et prévoir le refus ou l’absence de support.', 'Sur un profil sans permission enregistrée, aucune demande n’apparaît au chargement ; elle apparaît au bon moment et le refus laisse le parcours utilisable.'],
  [`${enName} permission is requested too early`, 'A request on page load without context prevents users understanding why the permission is useful.', `In startup code, locate the call to ${api} and the component triggering it.`, 'Move the request after an explicit action associated with the feature; explain its use and handle denial or lack of support.', 'In a profile without stored permission, no prompt appears on load; it appears at the right moment and denial leaves the journey usable.']);
rule(['paste-preventing-inputs'],
  ['Un champ empêche de coller du texte', 'Bloquer le collage gêne les gestionnaires de mots de passe et les personnes qui préparent leur saisie ailleurs.', 'Reproduire le collage dans le champ signalé et examiner ses gestionnaires paste, beforeinput et clavier.', 'Retirer le preventDefault ou la logique qui bloque le collage ; valider la valeur obtenue comme une saisie ordinaire.', 'Coller au clavier et via le menu, puis utiliser le remplissage automatique ; la valeur reste acceptée et validée normalement.'],
  ['An input prevents pasting', 'Blocking paste hinders password managers and people preparing input elsewhere.', 'Reproduce pasting in the flagged field and inspect its paste, beforeinput and keyboard handlers.', 'Remove preventDefault or logic blocking paste; validate the resulting value like normal input.', 'Paste by keyboard and context menu, then use autofill; the value is accepted and validated normally.']);
rule(['deprecations'],
  ['Le code utilise une fonctionnalité dépréciée', 'Une API destinée à disparaître peut casser lors d’une mise à jour du navigateur.', 'Dans Console ou Issues, ouvrir l’avertissement de dépréciation et remonter au script, à la ligne ou au paquet concernés.', 'Remplacer l’API selon la migration indiquée dans l’avertissement, ou mettre à jour la dépendance responsable. Tester la compatibilité des navigateurs supportés.', 'Rejouer le déclencheur : l’avertissement ciblé disparaît et la fonction continue à fonctionner.'],
  ['Code uses a deprecated feature', 'An API scheduled for removal may break after a browser update.', 'In Console or Issues, open the deprecation warning and trace it to the affected script, line or package.', 'Replace the API following the migration named in the warning, or update the responsible dependency. Test compatibility with supported browsers.', 'Repeat the trigger: the targeted warning disappears and the feature still works.']);
rule(['third-party-cookies'],
  ['Une fonction dépend de cookies tiers', 'Une intégration peut échouer lorsque le navigateur bloque ou partitionne les cookies tiers.', 'Dans Issues et Application, identifier le cookie, son domaine et le parcours qui dépend de lui sans copier sa valeur secrète.', 'Retirer les cookies non nécessaires et adapter l’intégration à une solution compatible avec les restrictions du navigateur. Pour un fournisseur, vérifier sa migration et le comportement sans cookie tiers.', 'Tester le parcours avec cookies tiers bloqués puis avec la politique habituelle ; connexion, consentement et intégrations nécessaires restent utilisables.'],
  ['A feature depends on third-party cookies', 'An integration may fail when the browser blocks or partitions third-party cookies.', 'In Issues and Application, identify the cookie, domain and dependent journey without copying its secret value.', 'Remove unnecessary cookies and adapt the integration to a solution compatible with browser restrictions. For a provider, check its migration and behaviour without third-party cookies.', 'Test with third-party cookies blocked and with the normal policy; sign-in, consent and required integrations remain usable.']);
rule(['valid-source-maps'],
  ['Des cartes de sources sont absentes ou invalides', 'Sans source maps valides, retrouver le code source d’une erreur dans un fichier compilé devient plus difficile.', 'Dans Sources et Réseau, inspecter sourceMappingURL du fichier signalé, la réponse du fichier .map et sa correspondance avec le build.', 'Générer des source maps correspondant exactement au fichier compilé et corriger leur livraison. Choisir une diffusion publique ou un téléversement privé à l’outil de diagnostic selon la confidentialité des sources.', 'Une erreur de test remonte à la bonne source et ligne dans l’environnement choisi. Une carte volontairement privée peut laisser ce contrôle public non satisfait.'],
  ['Source maps are missing or invalid', 'Without valid source maps, tracing an error in a compiled file to its source is harder.', 'In Sources and Network, inspect the flagged file’s sourceMappingURL, the .map response and correspondence with the build.', 'Generate source maps matching the compiled file exactly and fix their delivery. Choose public serving or private upload to the diagnostic tool according to source confidentiality.', 'A test error maps to the correct source and line in the chosen environment. An intentionally private map may leave this public check unsatisfied.']);
rule(['inspector-issues'],
  ['Le navigateur signale des problèmes dans Issues', 'Ce contrôle regroupe des incidents de natures différentes ; le sous-message indique l’effet et la correction applicables.', 'Dans DevTools → Issues, reproduire le chargement et développer l’incident correspondant pour relever son code, la ressource et le motif.', 'Appliquer la correction du sous-incident identifié, par exemple un attribut de cookie, une règle CORS ou une API obsolète. Ne pas modifier des politiques globales sans avoir identifié ce motif.', 'Rejouer la ressource ou la fonction : le sous-incident ciblé disparaît sans désactiver les protections du navigateur.'],
  ['The browser reports problems in Issues', 'This check groups different incidents; the individual message identifies the applicable effect and correction.', 'In DevTools → Issues, reproduce loading and expand the matching incident to identify its code, resource and reason.', 'Apply the identified sub-issue’s correction, such as a cookie attribute, CORS rule or deprecated API. Do not change global policies without identifying that reason.', 'Repeat the resource request or feature: the targeted sub-issue disappears without disabling browser protections.']);
rule(['bf-cache'],
  ['La page ne bénéficie pas du cache retour/avance', 'Revenir sur la page peut imposer un nouveau chargement au lieu d’une restauration immédiate.', 'Dans Application → Back/forward cache, lancer le test et lire les motifs de blocage de cette page et de ses cadres.', 'Corriger le motif effectivement indiqué : remplacer les gestionnaires unload par une gestion du cycle de vie adaptée, fermer puis rouvrir les ressources bloquantes si nécessaire, ou modifier l’intégration responsable.', 'Naviguer ailleurs puis revenir : la restauration fonctionne et les données qui doivent être fraîches sont mises à jour. Respecter les restrictions liées aux contenus sensibles.'],
  ['The page cannot use the back/forward cache', 'Returning to the page may require a reload instead of immediate restoration.', 'In Application → Back/forward cache, run the test and read blocking reasons for this page and its frames.', 'Fix the actual stated reason: replace unload handlers with suitable lifecycle handling, close and reopen blocking resources when needed, or change the responsible integration.', 'Navigate away and back: restoration works and data requiring freshness is updated. Respect restrictions for sensitive content.']);
rule(['http-status-code'],
  ['La page renvoie un statut HTTP en erreur', 'Une réponse en erreur peut empêcher les visiteurs et les moteurs d’accéder au contenu attendu.', 'Dans Réseau, lire le statut du document final et comparer son contenu avec la page attendue ; rechercher l’heure et la route dans les journaux serveur.', 'Corriger le routage, la ressource manquante ou l’erreur serveur reproduite. Pour une page volontairement supprimée, conserver un statut adapté plutôt que renvoyer artificiellement 200.', 'La page existante répond avec le statut et le contenu attendus ; les pages supprimées conservent leur signal explicite.'],
  ['The page returns an HTTP error status', 'An error response can prevent visitors and search engines reaching intended content.', 'In Network, read the final document status and compare content with the intended page; locate the time and route in server logs.', 'Fix the reproduced routing, missing resource or server error. For an intentionally removed page, retain a suitable status instead of artificially returning 200.', 'An existing page returns the intended status and content; removed pages retain their explicit signal.']);
rule(['link-text'],
  ['Des liens ont un libellé peu descriptif', 'Un texte comme « cliquez ici » peut manquer de sens lorsqu’un lien est lu isolément.', 'Retrouver les liens signalés dans le DOM et lire leur texte avec la destination et le contexte voisin.', 'Écrire un libellé décrivant la destination ou l’action, dans le contenu ou le gabarit qui produit le lien ; éviter les ajouts de mots-clés sans utilité.', 'Lire la liste des liens hors contexte : leurs destinations restent compréhensibles et correspondent aux pages ouvertes.'],
  ['Links have uninformative text', 'Text such as “click here” may lack meaning when a link is read in isolation.', 'Locate flagged links in the DOM and read their text alongside their destination and nearby context.', 'Write a label describing the destination or action in the content or template producing the link; avoid irrelevant keyword additions.', 'Read the link list out of context: destinations remain understandable and match the pages opened.']);
rule(['crawlable-anchors'],
  ['Des liens ne fournissent pas de destination explorable', 'Une navigation dépendant seulement de JavaScript peut ne pas être découverte comme un lien.', 'Inspecter les a signalés et leur href dans le HTML et le DOM rendu ; distinguer navigation et action locale.', 'Pour naviguer, utiliser un lien a avec un href réel et accessible. Pour une action locale, utiliser un bouton ; ne pas ajouter de faux href="#" pour satisfaire le contrôle.', 'Ouvrir le lien directement et dans un nouvel onglet ; il mène au contenu voulu sans dépendre du seul gestionnaire de clic.'],
  ['Links lack crawlable destinations', 'Navigation relying solely on JavaScript may not be discovered as a link.', 'Inspect flagged a elements and their href in HTML and rendered DOM; distinguish navigation from local actions.', 'For navigation, use an a link with a real accessible href. For local actions, use a button; do not add a fake href="#" merely to satisfy the check.', 'Open the link directly and in a new tab; it reaches intended content without relying solely on a click handler.']);
rule(['robots-txt'],
  ['Le fichier robots.txt contient des directives invalides', 'Une syntaxe incorrecte peut empêcher les robots d’appliquer les restrictions voulues.', 'Ouvrir /robots.txt à l’origine auditée et retrouver les lignes signalées, leur groupe User-agent et la réponse HTTP.', 'Corriger la syntaxe et les chemins des règles pour les robots visés. Vérifier l’intention avant de retirer un Disallow ; robots.txt ne protège pas des données privées.', 'Le fichier est lisible et les règles s’appliquent aux URL voulues dans l’outil de test du moteur concerné.'],
  ['Robots.txt contains invalid directives', 'Incorrect syntax may prevent crawlers applying intended restrictions.', 'Open /robots.txt at the audited origin and locate flagged lines, their User-agent group and HTTP response.', 'Correct rule syntax and paths for target crawlers. Check intent before removing a Disallow; robots.txt does not protect private data.', 'The file is readable and rules apply to intended URLs in the relevant search engine’s testing tool.']);
rule(['hreflang'],
  ['Les variantes linguistiques sont mal déclarées', 'Des annotations hreflang invalides peuvent empêcher les moteurs de relier les bonnes versions linguistiques.', 'Dans le head, les en-têtes ou le sitemap concernés, retrouver les hreflang signalés et visiter leurs destinations.', 'Utiliser des codes langue/région valides et des URL absolues vers les bonnes variantes. Rendre les relations réciproques et inclure la page elle-même dans l’ensemble approprié.', 'Chaque variante cible répond correctement et déclare le même ensemble réciproque de versions ; aucune langue ne pointe vers le mauvais contenu.'],
  ['Language alternatives are incorrectly declared', 'Invalid hreflang annotations may prevent search engines connecting the correct language versions.', 'In the relevant head, headers or sitemap, locate flagged hreflang annotations and visit their destinations.', 'Use valid language/region codes and absolute URLs for the correct variants. Make relationships reciprocal and include the page itself in the appropriate set.', 'Each target variant responds correctly and declares the same reciprocal version set; no language points to the wrong content.']);
rule(['canonical'],
  ['L’adresse canonique est incohérente', 'Une indication canonique invalide ou contradictoire peut orienter les moteurs vers une autre version du contenu.', 'Lire rel="canonical" dans le head rendu et les éventuels en-têtes Link ; comparer à la destination finale et aux variantes de cette page.', 'Définir une adresse canonique absolue cohérente vers la version représentative accessible. Supprimer les déclarations contradictoires et aligner liens internes et sitemap.', 'La cible répond sans erreur, correspond au contenu et ne contredit pas les autres indications d’indexation ; l’outil du moteur peut ensuite confirmer la canonique retenue.'],
  ['The canonical address is inconsistent', 'An invalid or conflicting canonical indication may direct search engines to another version of the content.', 'Read rel="canonical" in the rendered head and any Link headers; compare with the final destination and page variants.', 'Set a consistent absolute canonical address to the accessible representative version. Remove conflicting declarations and align internal links and sitemap.', 'The target responds successfully, matches the content and does not conflict with other indexing directives; the search engine’s tool can later confirm its selected canonical.']);

const tlsReference = 'https://developer.mozilla.org/en-US/docs/Web/Security/Defenses/Transport_Layer_Security';
for (const [id,attribute] of [['10010','HttpOnly'],['10011','Secure'],['10054','SameSite']]) rule([`zap.alert.${id}`],
  [`Un cookie est émis sans ${attribute}`, 'L’attribut manquant peut élargir l’exposition du cookie ; examiner son rôle avant de modifier les options.', 'Dans Réseau, ouvrir la réponse de la page et retrouver l’occurrence Set-Cookie indiquée. Identifier le composant qui produit cet en-tête.', attribute==='HttpOnly'?'Activer HttpOnly pour les cookies de session ou sensibles. Si JavaScript doit lire un cookie non sensible, documenter cette exception et séparer les secrets de session.':attribute==='Secure'?'Activer Secure dans les options du cookie et servir le parcours en HTTPS. Vérifier aussi la configuration du proxy si l’application détecte mal HTTPS.':'Définir SameSite=Lax ou Strict selon le parcours ; pour un usage tiers nécessaire, SameSite=None exige Secure. Tester notamment les retours de connexion et intégrations externes.', 'Rejouer le parcours, vérifier les attributs de cette réponse et confirmer que la session et les intégrations nécessaires fonctionnent.'],
  [`A cookie is emitted without ${attribute}`, 'The missing attribute may increase cookie exposure; inspect its purpose before changing options.', 'In Network, open the page response and locate the listed Set-Cookie entry. Identify the component emitting this header.', attribute==='HttpOnly'?'Enable HttpOnly for session or sensitive cookies. If JavaScript must read a non-sensitive cookie, document the exception and separate session secrets.':attribute==='Secure'?'Enable Secure in cookie options and serve the journey over HTTPS. Check proxy configuration if the application misidentifies HTTPS.':'Set SameSite=Lax or Strict as appropriate; necessary third-party use requires SameSite=None with Secure. Test sign-in callbacks and external integrations.', 'Repeat the journey, check this response’s attributes and confirm session and required integrations still work.'], 'zap', `https://www.zaproxy.org/docs/alerts/${id}/`);
rule(['zap.alert.10036'],
  ['L’en-tête Server expose une version logicielle', 'Cette information facilite l’identification du logiciel ; elle ne prouve pas une vulnérabilité.', 'Dans la réponse indiquée, lire Server et identifier le serveur ou proxy qui produit cet en-tête.', 'Désactiver la version détaillée dans la configuration du serveur ou proxy, par exemple server_tokens off pour nginx ; maintenir le logiciel à jour.', 'La réponse ne divulgue plus la version précise ; le site et le suivi opérationnel fonctionnent toujours.'],
  ['The Server header exposes a software version', 'This helps identify the software; it does not prove a vulnerability.', 'Read Server in the listed response and identify the server or proxy emitting it.', 'Disable detailed versions in server or proxy configuration, for example server_tokens off in nginx; keep the software updated.', 'The response no longer discloses the exact version; the site and operational monitoring still work.'], 'zap', 'https://www.zaproxy.org/docs/alerts/10036/');
rule(['zap.alert.10040'],
  ['Une page HTTPS référence du contenu HTTP', 'Le navigateur peut bloquer ou mettre à niveau la ressource ; son fonctionnement et sa protection doivent être vérifiés.', 'Dans la réponse HTML à la ligne indiquée, retrouver l’URL HTTP et l’attribut qui la charge ; vérifier la requête correspondante dans Réseau.', 'Remplacer la référence par une URL HTTPS réellement disponible. Si le fournisseur ne sert pas cette ressource en HTTPS, la remplacer ou la retirer ; ne pas désactiver la protection du navigateur.', 'Recharger sur un profil propre : la ressource utile répond en HTTPS sans contenu mixte et le parcours fonctionne.'],
  ['An HTTPS page references HTTP content', 'The browser may block or upgrade the resource; verify its behaviour and protection.', 'At the indicated HTML response line, locate the HTTP URL and loading attribute; inspect its request in Network.', 'Replace it with an actually available HTTPS URL. If the provider does not serve it over HTTPS, replace or remove the resource; do not disable browser protection.', 'Reload in a clean profile: the needed resource responds over HTTPS without mixed content and the journey works.'], 'zap', 'https://www.zaproxy.org/docs/alerts/10040/');
rule(['zap.alert.10096'],
  ['Une valeur ressemble à un horodatage', 'Un horodatage public est souvent normal. Le signal devient pertinent seulement s’il révèle une information sensible ou un comportement exploitable.', 'Retrouver la valeur à la ligne ou dans l’en-tête indiqué ; vérifier qu’il s’agit bien d’un horodatage et comprendre pourquoi il est publié.', 'Si cette information est sensible et inutile au client, la retirer ou réduire sa précision dans la réponse. Si elle est publique et nécessaire, documenter le signal comme acceptable ; ne pas supprimer un identifiant ou une constante sur la seule détection.', 'La réponse conserve les données nécessaires au parcours sans divulgation sensible ; la qualification de cette alerte est documentée.'],
  ['A value resembles a timestamp', 'Public timestamps are often normal. This signal matters only if it reveals sensitive information or exploitable behaviour.', 'Locate the value at the indicated line or header; confirm it is a timestamp and understand why it is published.', 'If sensitive and unnecessary to the client, remove it or reduce precision in the response. If public and necessary, document the signal as acceptable; do not remove an identifier or constant based solely on detection.', 'The response retains needed data without sensitive disclosure; the alert qualification is documented.'], 'zap', 'https://www.zaproxy.org/docs/alerts/10096/');
rule(['zap.alert.10055'],
  ['La politique CSP contient des directives à examiner', 'Une politique trop permissive limite la protection contre certains contenus injectés. Les motifs précis figurent avec l’en-tête concerné.', 'Dans Réseau, ouvrir la réponse de la page et lire Content-Security-Policy. Comparer les directives citées par ZAP, sans remplacer toute la politique.', 'Définir les directives manquantes et remplacer les jokers par les origines nécessaires. Pour style-src unsafe-inline, inventorier les styles inline puis tester des feuilles externes ou des nonces/hachages appropriés en Report-Only avant application.', 'Tester le parcours et les violations CSP, puis refaire la requête et l’analyse passive. Les directives ciblées sont corrigées sans bloquer les ressources légitimes.'],
  ['The CSP policy contains directives to review', 'An overly permissive policy limits protection against some injected content. Specific reasons appear with the affected header.', 'In Network, open the page response and read Content-Security-Policy. Compare the directives named by ZAP without replacing the entire policy.', 'Define missing directives and replace wildcards with required origins. For style-src unsafe-inline, inventory inline styles and test external stylesheets or appropriate nonces/hashes in Report-Only before enforcement.', 'Test the journey and CSP violations, then repeat the request and passive analysis. Targeted directives are fixed without blocking legitimate resources.'],
  'zap', 'https://www.zaproxy.org/docs/alerts/10055/');
rule(['zap.alert.10202'],
  ['La protection CSRF de certains formulaires reste à vérifier', 'ZAP ne reconnaît pas de jeton anti-CSRF dans le HTML reçu. Cela ne démontre pas que le serveur accepte une requête forgée : une protection JavaScript ou serveur peut exister.', 'Retrouver les formulaires avec les sélecteurs relevés. Sur un environnement de test, observer leur requête et vérifier si elle utilise une session, un jeton dans un en-tête et une validation Origin/CSRF côté serveur.', 'Si une action utilise les droits d’une session sans protection, activer le mécanisme CSRF du framework et valider le jeton côté serveur. Si une protection équivalente existe déjà, documenter ce signal comme non confirmé plutôt que d’ajouter un champ caché sans validation.', 'En test, une requête authentifiée avec jeton absent ou invalide doit être rejetée, tandis que le formulaire légitime fonctionne. Une analyse du seul HTML ne suffit pas à prouver cette protection.'],
  ['CSRF protection needs verification on some forms', 'ZAP does not recognise an anti-CSRF token in received HTML. This does not prove that the server accepts a forged request: JavaScript or server protection may exist.', 'Locate the forms using the reported selectors. In a test environment, inspect their requests and check session use, header tokens and server-side Origin/CSRF validation.', 'If an action uses session privileges without protection, enable the framework’s CSRF mechanism and validate the token on the server. If equivalent protection already exists, document this unconfirmed signal rather than adding an unvalidated hidden field.', 'In testing, an authenticated request with a missing or invalid token must be rejected while the legitimate form works. HTML inspection alone cannot prove this protection.'],
  'zap', 'https://www.zaproxy.org/docs/alerts/10202/');
function tls(id: string, fr: Guidance, en: Guidance) { rule([id], fr, en, 'ssl', tlsReference); }
tls('ssl.certificate.valid',
  ['Le certificat TLS doit être vérifié', 'Un certificat expiré, non approuvé ou ne couvrant pas le nom demandé peut bloquer la connexion.', 'Dans SSL Labs puis le panneau Security, relever le nom couvert, la période de validité et la chaîne du certificat réellement servi par chaque terminaison.', 'Installer un certificat valide pour le nom demandé avec les intermédiaires nécessaires ; corriger la sélection SNI sur le proxy ou CDN si le mauvais certificat est servi.', 'Chaque terminaison sert la bonne chaîne et le navigateur ouvre HTTPS sans erreur pour les noms utilisés.'],
  ['The TLS certificate needs checking', 'An expired, untrusted or mismatched certificate can block the connection.', 'In SSL Labs and then Security, inspect names, validity period and the chain actually served by each endpoint.', 'Install a valid certificate for the requested name with required intermediates; fix SNI selection on the proxy or CDN if the wrong certificate is served.', 'Each endpoint serves the correct chain and the browser opens HTTPS without errors for the names used.']);
tls('ssl.certificate.expiry_days',
  ['Le certificat approche de son renouvellement', 'Un renouvellement manqué peut provoquer une interruption HTTPS à l’expiration.', 'Relever la date notAfter du certificat servi et contrôler le journal de renouvellement du gestionnaire de certificats.', 'Renouveler le certificat puis installer ou recharger la nouvelle version sur chaque terminaison. Corriger le mécanisme automatique et ses alertes si le renouvellement ne s’exécute pas.', 'La date d’expiration effectivement servie est repoussée et le prochain renouvellement automatique est vérifié.'],
  ['The certificate is approaching renewal', 'A missed renewal can interrupt HTTPS when the certificate expires.', 'Read the served certificate’s notAfter date and inspect the certificate manager’s renewal log.', 'Renew the certificate, then install or reload the new version on every endpoint. Fix automatic renewal and alerting if renewal is not running.', 'The expiration date actually served is extended and the next automatic renewal is verified.']);
for (const version of ['1.2', '1.3']) tls(`ssl.protocols.tls${version.replace('.', '')}`,
  [`TLS ${version} n’est pas disponible sur une terminaison`, 'L’absence d’une version TLS peut limiter la compatibilité ou l’usage des protocoles récents.', `Dans SSL Labs, identifier la terminaison qui n’accepte pas TLS ${version} ; vérifier la version du serveur, du proxy ou du CDN qui termine TLS.`, `Activer TLS ${version} sur cette terminaison avec une bibliothèque compatible et des suites adaptées ; tester les clients à supporter avant de modifier les autres versions.`, `Une négociation forcée en TLS ${version} réussit sur les terminaisons concernées et les clients supportés restent compatibles.`],
  [`TLS ${version} is unavailable on an endpoint`, 'A missing TLS version can limit compatibility or use of newer protocols.', `In SSL Labs, identify the endpoint not accepting TLS ${version}; check the server, proxy or CDN version terminating TLS.`, `Enable TLS ${version} on that endpoint with a compatible library and suitable cipher suites; test supported clients before changing other versions.`, `A forced TLS ${version} handshake succeeds on affected endpoints and supported clients remain compatible.`]);
tls('ssl.protocols.legacy_disabled',
  ['D’anciens protocoles TLS restent acceptés', 'Des protocoles obsolètes peuvent permettre des connexions avec des protections insuffisantes.', 'Dans la liste de protocoles SSL Labs, identifier précisément les anciennes versions acceptées par chaque terminaison.', 'Désactiver SSL et TLS obsolètes sur le point qui termine la connexion, après identification des clients dépendants et préparation de leur mise à jour. Conserver les versions modernes nécessaires.', 'Les négociations avec les versions retirées échouent ; TLS moderne et les clients supportés continuent de fonctionner.'],
  ['Legacy TLS protocols are still accepted', 'Obsolete protocols can allow connections with inadequate protections.', 'In SSL Labs’ protocol list, identify the exact legacy versions accepted by each endpoint.', 'Disable obsolete SSL and TLS versions where the connection terminates, after identifying dependent clients and preparing their upgrade. Retain required modern versions.', 'Handshakes with removed versions fail; modern TLS and supported clients continue to work.']);

rule(['zap.alert.10098'],
  ['Une réponse autorise des lectures depuis d’autres sites', 'Une politique CORS trop ouverte peut permettre à des sites non prévus de lire une réponse. Le risque dépend des données renvoyées et de leur protection.', 'Dans Réseau, identifier la réponse signalée et comparer Access-Control-Allow-Origin aux origines légitimes qui doivent la lire. Vérifier aussi si le contenu est public ou sensible.', 'Limiter les origines autorisées aux clients prévus, ou retirer CORS si aucune lecture entre origines n’est nécessaire. Protéger les données sensibles par un contrôle d’accès ; CORS ne remplace pas l’authentification.', 'Tester une origine autorisée et une origine non autorisée dans un navigateur : seule la lecture voulue fonctionne, et l’API refuse les accès non autorisés indépendamment de CORS.'],
  ['A response allows reads from other sites', 'An overly open CORS policy may let unintended sites read a response. Risk depends on the returned data and its protection.', 'In Network, identify the flagged response and compare Access-Control-Allow-Origin with legitimate reading origins. Also determine whether content is public or sensitive.', 'Restrict allowed origins to intended clients, or remove CORS if cross-origin reads are unnecessary. Protect sensitive data with access control; CORS does not replace authentication.', 'Test an allowed and a disallowed origin in a browser: only intended reading works, and the API rejects unauthorised access independently of CORS.'],
  'zap', 'https://www.zaproxy.org/docs/alerts/10098/');
rule(['zap.alert.10037'],
  ['L’en-tête X-Powered-By expose le logiciel utilisé', 'Une bannière peut faciliter l’identification d’une technologie ou de sa version ; elle ne prouve pas une vulnérabilité.', 'Dans Réseau, lire X-Powered-By sur la réponse signalée et identifier l’application ou le proxy qui ajoute cet en-tête.', 'Désactiver cette bannière au niveau du composant qui l’émet et vérifier que les mises à jour de sécurité sont appliquées. Masquer une version ne corrige pas les failles du logiciel.', 'Recharger la réponse publique, y compris une page d’erreur : la bannière superflue est absente et le service continue de répondre correctement.'],
  ['The X-Powered-By header exposes the software used', 'A banner may help identify a technology or version; it does not prove a vulnerability.', 'In Network, read X-Powered-By on the flagged response and identify the application or proxy adding the header.', 'Disable the banner in the component emitting it and verify security updates are applied. Hiding a version does not fix software vulnerabilities.', 'Reload the public response, including an error page: the unnecessary banner is absent and the service still responds correctly.'],
  'zap', 'https://www.zaproxy.org/docs/alerts/10037/');
